package com.simonkaring.voltlink.okf

import com.simonkaring.voltlink.core.telemetry.TelemetryMetric
import com.simonkaring.voltlink.core.vehicles.AbrpProfileLoader
import com.simonkaring.voltlink.core.vehicles.VehicleCatalog
import com.simonkaring.voltlink.core.vehicles.VehicleModelEntry
import com.simonkaring.voltlink.core.vehicles.VehicleProfileId
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.File
import java.util.Locale

/**
 * Builds and validates the Android `knowledge/` Open Knowledge Format bundle.
 *
 * The iOS bundle is generated by `swift run VoltLinkCLI okf export` from the live Swift types;
 * this is the Kotlin equivalent. It lives in the unit-test source set so it can instantiate the
 * profiles the app ships (the ABRP loader takes an asset reader, so no Android runtime is
 * needed) and so `./gradlew testDebugUnitTest` fails when the checked-in bundle drifts from its
 * sources.
 */
object KnowledgeBundle {
    const val okfVersion = "0.2"
    const val generatedBy = "voltlink-okf/1.0"
    const val exportCommand =
        "./gradlew testDebugUnitTest --tests '*KnowledgeBundleTest' -Pokf.export=true"

    /** Directories the generator owns; concepts here that no longer exist are deleted on export. */
    private val generatedDirectories = listOf("vehicles", "telemetry", "diagnostics")

    private val rootSections = listOf(
        "architecture" to "Architecture",
        "vehicles" to "Vehicle Profiles",
        "telemetry" to "Telemetry Metrics",
        "diagnostics" to "Diagnostic Trouble Codes",
    )

    private val json = Json { ignoreUnknownKeys = true }

    data class ExportResult(val written: List<String>, val removed: List<String>)

    /** Points the ABRP loader at the bundled PID definitions on disk. */
    fun installAssets(assets: File) {
        AbrpProfileLoader.install { path ->
            File(assets, path).takeIf { it.isFile }?.readText()
        }
    }

    // MARK: - Generated concepts

    /** Every generated concept as `bundle-relative path -> markdown`. */
    fun conceptFiles(assets: File): Map<String, String> {
        val files = LinkedHashMap<String, String>()
        files.putAll(profileConcepts(assets))
        files.putAll(metricConcepts())
        files.putAll(dtcConcepts(assets))
        return files
    }

    private fun profileConcepts(assets: File): Map<String, String> {
        val catalog = readCatalog(assets)
        val modelsByProfile = catalog.flatMap { it.models }.groupBy { it.profileId }

        val ids = VehicleProfileId.entries.sortedBy { it.displayName.lowercase(Locale.US) }
        return ids.associate { id ->
            val profile = id.makeProfile()
            val models = modelsByProfile[id].orEmpty()
            val metrics = profile.supportedMetrics.sortedBy { it.displayName.lowercase(Locale.US) }
            val polling = profile.pollingCommands
            val initialization = profile.initializationCommands

            val body = mutableListOf(
                "# Profile",
                "",
                "| Attribute | Value |",
                "| --- | --- |",
                "| Registry ID | `${id.name}` |",
                "| Display name | ${id.displayName} |",
                "| Profile class | `${profile::class.simpleName}` |",
                "| Electric vehicle | ${if (profile.isElectricVehicle) "Yes" else "No"} |",
                "| Usable battery capacity | ${number(profile.batteryUsableCapacityKWh)} kWh |",
                "| Catalog models | ${models.size} |",
                "| Polling commands | ${polling.size} |",
                "| ABRP definition | ${if (id.isCommunityProfile) "Bundled asset" else "None (compiled in)"} |",
            )

            if (metrics.isNotEmpty()) {
                body += listOf("", "# Supported Metrics", "")
                for (metric in metrics) {
                    body += "- [${metric.displayName}](/telemetry/${fileName(metric.name)}.md) — `${metric.name}` (${metric.unitSymbol})"
                }
            }

            body += listOf("", "# Polling Commands", "")
            if (polling.isEmpty()) {
                body += "This profile has no polling commands."
            } else {
                body += "```text"
                body += polling
                body += "```"
            }

            if (initialization.isNotEmpty()) {
                body += listOf("", "# Initialization Commands", "", "```text")
                body += initialization
                body += "```"
            }

            if (models.isNotEmpty()) {
                body += listOf("", "# Catalog Coverage", "")
                for (model in models.take(8)) {
                    body += "- ${model.brandName} ${model.modelName} · ${model.years} · ${model.telemetrySupport.label}"
                }
                if (models.size > 8) body += "- …and ${models.size - 8} more catalog entries"
            }

            "vehicles/${fileName(id.name)}.md" to render(
                type = "Vehicle Profile",
                title = id.displayName,
                description = "${id.displayName} vehicle profile with " +
                    "${plural(polling.size, "polling command", "polling commands")} and " +
                    "${plural(metrics.size, "telemetry metric", "telemetry metrics")}.",
                tags = listOf("vehicle-profile", if (profile.isElectricVehicle) "ev" else "ice"),
                sources = listOf(
                    Source(
                        "registry",
                        "../app/src/main/java/com/simonkaring/voltlink/core/vehicles/VehicleProfileRegistry.kt",
                        "Vehicle profile registry",
                    ),
                    Source(
                        "catalog",
                        "../app/src/main/assets/vehicle_catalog.json",
                        "Bundled vehicle catalog",
                    ),
                ),
                body = body,
            )
        }
    }

    private fun metricConcepts(): Map<String, String> {
        val profiles = VehicleProfileId.entries.associateWith { id ->
            TelemetryMetric.includingDerivedMetrics(id.makeProfile().supportedMetrics)
        }

        return TelemetryMetric.entries.associate { metric ->
            val producedBy = profiles.filterValues { metric in it }.keys
                .sortedBy { it.displayName.lowercase(Locale.US) }

            val body = mutableListOf(
                "# Definition",
                "",
                "`${metric.displayName}` (`${metric.name}`) is a telemetry metric reported in `${metric.unitSymbol}`.",
                "",
                "# Range",
                "",
                "| Attribute | Value |",
                "| --- | --- |",
                "| Unit | `${metric.unitSymbol}` |",
                "| Typical range | ${range(metric.rangeStart, metric.rangeEnd)} |",
                "| Decimal places | ${metric.decimalPlaces} |",
            )

            body += listOf("", "# Produced By", "")
            if (producedBy.isEmpty()) {
                body += "No profile in the Android registry currently reports this metric."
            } else {
                for (id in producedBy) {
                    body += "- [${id.displayName}](/vehicles/${fileName(id.name)}.md)"
                }
            }

            val notes = metricNotes(metric)
            if (notes.isNotEmpty()) {
                body += listOf("", "# Notes", "")
                body += notes.map { "- $it" }
            }

            "telemetry/${fileName(metric.name)}.md" to render(
                type = "Telemetry Metric",
                title = metric.displayName,
                description = "${metric.displayName} telemetry metric in ${metric.unitSymbol}, " +
                    "produced by ${plural(producedBy.size, "vehicle profile", "vehicle profiles")}.",
                tags = listOf("telemetry-metric", "core"),
                sources = listOf(
                    Source(
                        "metric-catalog",
                        "../app/src/main/java/com/simonkaring/voltlink/core/telemetry/TelemetryMetric.kt",
                        "Telemetry metric catalog",
                    ),
                ),
                body = body,
            )
        }
    }

    private fun dtcConcepts(assets: File): Map<String, String> {
        val curated = readCuratedDtcs(assets)
        return curated.associate { dtc ->
            val body = mutableListOf("# Meaning", "", dtc.description.ifBlank { "No curated description." })

            if (dtc.symptoms.isNotEmpty()) {
                body += listOf("", "# Symptoms", "")
                body += dtc.symptoms.map { "- $it" }
            }
            if (dtc.possibleFixes.isNotEmpty()) {
                body += listOf("", "# Possible Fixes", "")
                body += dtc.possibleFixes.map { "- $it" }
            }

            body += listOf(
                "",
                "# Classification",
                "",
                "| Attribute | Value |",
                "| --- | --- |",
                "| Category | ${dtc.category} |",
                "| Severity | ${dtc.severity} |",
            )

            "diagnostics/${dtc.code}.md" to render(
                type = "DTC Definition",
                title = dtc.code,
                description = "${dtc.category} trouble code ${dtc.code}: ${dtc.title}.",
                tags = listOf("dtc", slug(dtc.category)),
                sources = listOf(
                    Source(
                        "curated-dtc",
                        "../app/src/main/assets/dtc_definitions.json",
                        "Curated VoltLink DTC definitions",
                    ),
                ),
                body = body,
            )
        }
    }

    // MARK: - Indexes

    /** Renders `index.md` for the bundle root and every directory that holds concepts. */
    fun indexFiles(files: Map<String, String>): Map<String, String> {
        data class Entry(val path: String, val title: String, val description: String?, val type: String)

        val entriesByDirectory = mutableMapOf<String, MutableList<Entry>>()
        for ((path, text) in files) {
            if (!path.endsWith(".md")) continue
            val name = path.substringAfterLast('/')
            if (name == "index.md" || name == "log.md") continue
            val fields = frontmatterFields(text) ?: continue
            val type = fields["type"].orEmpty()
            if (type.isEmpty()) continue
            val directory = path.substringBeforeLast('/', "")
            entriesByDirectory.getOrPut(directory) { mutableListOf() } += Entry(
                path = path,
                title = fields["title"]?.takeIf { it.isNotEmpty() } ?: name.removeSuffix(".md"),
                description = fields["description"]?.takeIf { it.isNotEmpty() },
                type = type,
            )
        }

        fun sorted(directory: String) = entriesByDirectory[directory].orEmpty().sortedWith(
            compareBy({ it.title.lowercase(Locale.US) }, { it.path }),
        )

        fun line(entry: Entry, link: String) = entry.description
            ?.let { "* [${entry.title}]($link) - $it" }
            ?: "* [${entry.title}]($link)"

        val indexes = LinkedHashMap<String, String>()

        for (directory in entriesByDirectory.keys.filter { it.isNotEmpty() }) {
            val lines = mutableListOf<String>()
            val grouped = sorted(directory).groupBy { it.type }
            for (type in grouped.keys.sorted()) {
                lines += "# $type"
                for (entry in grouped.getValue(type)) {
                    val prefix = "$directory/"
                    val link = if (entry.path.startsWith(prefix)) entry.path.removePrefix(prefix) else entry.path
                    lines += line(entry, link)
                }
                lines += ""
            }
            indexes["$directory/index.md"] = lines.joinToString("\n")
        }

        val rootLines = mutableListOf("---", "okf_version: \"$okfVersion\"", "---", "")
        for ((directory, heading) in rootSections) {
            val entries = sorted(directory)
            if (entries.isEmpty()) continue
            rootLines += "# $heading"
            rootLines += entries.map { line(it, it.path) }
            rootLines += ""
        }
        val known = rootSections.map { it.first }.toSet()
        for (directory in entriesByDirectory.keys.filter { it.isNotEmpty() && it !in known }.sorted()) {
            rootLines += "# ${directory.replaceFirstChar { it.uppercase() }}"
            rootLines += sorted(directory).map { line(it, it.path) }
            rootLines += ""
        }
        indexes["index.md"] = rootLines.joinToString("\n")

        return indexes
    }

    // MARK: - Export and check

    /** Writes generated concepts and every index, removing concepts that no longer exist. */
    fun write(bundleRoot: File, assets: File): ExportResult {
        val concepts = conceptFiles(assets)
        val removed = mutableListOf<String>()

        for (directory in generatedDirectories) {
            val existing = File(bundleRoot, directory).listFiles().orEmpty()
            for (file in existing.sortedBy { it.name }) {
                if (file.extension != "md" || file.name == "index.md") continue
                val relative = "$directory/${file.name}"
                if (!concepts.containsKey(relative)) {
                    file.delete()
                    removed += relative
                }
            }
        }

        concepts.forEach { (path, content) -> File(bundleRoot, path).writeTextEnsuringParent(content) }

        val allFiles = readMarkdownFiles(bundleRoot).toMutableMap().apply { putAll(concepts) }
        val indexes = indexFiles(allFiles)
        indexes.forEach { (path, content) -> File(bundleRoot, path).writeTextEnsuringParent(content) }

        return ExportResult(written = (concepts.keys + indexes.keys).sorted(), removed = removed.sorted())
    }

    /** OKF v0.2 conformance plus drift against the generated concepts and indexes. */
    fun check(bundleRoot: File, assets: File): List<String> {
        if (!bundleRoot.isDirectory) {
            return listOf("Bundle directory is missing: ${bundleRoot.path}. Run `$exportCommand`.")
        }
        val files = readMarkdownFiles(bundleRoot)
        if (files.isEmpty()) {
            return listOf("No markdown files in ${bundleRoot.path}. Run `$exportCommand`.")
        }

        val issues = mutableListOf<String>()
        for ((path, text) in files.toSortedMap()) {
            val name = path.substringAfterLast('/')
            if (name == "index.md" || name == "log.md") {
                if (path == "index.md") {
                    val version = frontmatterFields(text)?.get("okf_version")
                    if (version != okfVersion) {
                        issues += "index.md: expected okf_version \"$okfVersion\", found ${version ?: "none"}"
                    }
                }
                continue
            }

            val fields = frontmatterFields(text)
            if (fields == null) {
                issues += "$path: missing YAML frontmatter"
                continue
            }
            if (fields["type"].isNullOrEmpty()) issues += "$path: frontmatter has no type"
            if (fields["title"].isNullOrEmpty()) issues += "$path: frontmatter has no title"
            if (fields["description"].isNullOrEmpty()) issues += "$path: frontmatter has no description"

            for (link in markdownLinks(text)) {
                val resolved = resolve(link, path)
                if (!files.containsKey(resolved)) {
                    issues += "$path: link target $link does not exist in the bundle"
                }
            }
        }

        val concepts = conceptFiles(assets)
        for ((path, expected) in concepts) {
            val actual = files[path]
            if (actual != expected) {
                issues += "$path: ${if (actual == null) "missing" else "out of date"}; run `$exportCommand`"
            }
        }

        for (directory in generatedDirectories) {
            for (file in File(bundleRoot, directory).listFiles().orEmpty()) {
                if (file.extension != "md" || file.name == "index.md") continue
                val relative = "$directory/${file.name}"
                if (!concepts.containsKey(relative)) {
                    issues += "$relative: no longer generated; run `$exportCommand`"
                }
            }
        }

        for ((path, expected) in indexFiles(files)) {
            if (files[path] != expected) issues += "$path: index out of date; run `$exportCommand`"
        }

        return issues
    }

    // MARK: - Rendering helpers

    private data class Source(val id: String, val resource: String, val title: String)

    private fun render(
        type: String,
        title: String,
        description: String,
        tags: List<String>,
        sources: List<Source>,
        body: List<String>,
    ): String = buildString {
        appendLine("---")
        appendLine("type: \"$type\"")
        appendLine("title: ${quoted(title)}")
        appendLine("description: ${quoted(description)}")
        appendLine("tags: [${tags.joinToString(", ") { quoted(it) }}]")
        appendLine("sources:")
        for (source in sources) {
            appendLine("- id: ${quoted(source.id)}")
            appendLine("  resource: ${quoted(source.resource)}")
            appendLine("  title: ${quoted(source.title)}")
        }
        appendLine("generated: { by: \"$generatedBy\" }")
        appendLine("status: \"stable\"")
        appendLine("---")
        appendLine()
        append(body.joinToString("\n"))
        appendLine()
    }

    private fun metricNotes(metric: TelemetryMetric): List<String> = buildList {
        when (metric) {
            TelemetryMetric.INSTANT_EFFICIENCY, TelemetryMetric.REGEN_POWER ->
                add("Derived from speed and power; `VehicleDataManager` adds it to the live metric set only while both inputs are available.")
            TelemetryMetric.TRIP_AVERAGE_CONSUMPTION ->
                add("The default dashboard layout shows this tile, but nothing in the Android pipeline writes `TelemetrySnapshot.tripAverageConsumption` yet, so the tile reads `--`.")
            else -> Unit
        }
        if (metric.isCommunityMetric) {
            add("Experimental Mercedes-Benz EQA community metric; decoded by `MercedesEqaObdbProfile`.")
        }
    }

    private fun quoted(value: String) = "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\""

    private fun plural(count: Int, singular: String, plural: String) =
        if (count == 1) "1 $singular" else "$count $plural"

    private fun range(start: Double, end: Double) = "${number(start)}–${number(end)}"

    private fun number(value: Double): String =
        if (value == value.toLong().toDouble()) value.toLong().toString() else String.format(Locale.US, "%.1f", value)

    private fun slug(value: String) =
        value.lowercase(Locale.US).replace(" / ", "-").replace(' ', '-').replace("/", "-")

    private fun fileName(identifier: String) = identifier.lowercase(Locale.US)

    // MARK: - Files

    private fun File.writeTextEnsuringParent(content: String) {
        parentFile?.mkdirs()
        writeText(content)
    }

    private fun readMarkdownFiles(root: File): Map<String, String> {
        val prefix = root.absoluteFile.path + "/"
        return root.walkTopDown()
            .filter { it.isFile && it.extension == "md" }
            .associate { it.absolutePath.removePrefix(prefix) to it.readText() }
    }

    /**
     * Parses the small subset of YAML frontmatter the bundle uses: top-level `key: value`
     * scalars. Nested blocks (`sources`, `generated`) are not needed by the indexer.
     */
    private fun frontmatterFields(text: String): Map<String, String>? {
        if (!text.startsWith("---\n")) return null
        val end = text.indexOf("\n---", startIndex = 3)
        if (end < 0) return null
        val fields = mutableMapOf<String, String>()
        for (line in text.substring(4, end).lines()) {
            if (line.startsWith(" ") || line.startsWith("-") || line.isBlank()) continue
            val separator = line.indexOf(':')
            if (separator <= 0) continue
            val key = line.substring(0, separator).trim()
            val raw = line.substring(separator + 1).trim()
            fields[key] = raw.removeSurrounding("\"")
        }
        return fields
    }

    private fun markdownLinks(text: String): List<String> =
        Regex("\\[[^\\]]*]\\(([^)\\s]+\\.md)\\)")
            .findAll(text)
            .map { it.groupValues[1] }
            .toList()

    /**
     * Resolves a markdown link to a bundle path. A leading `/` means bundle-root absolute (the
     * convention the iOS bundle uses); anything else is relative to the containing concept.
     */
    private fun resolve(link: String, fromPath: String): String {
        val clean = link.substringBefore('#')
        val segments = if (clean.startsWith("/")) {
            mutableListOf()
        } else {
            fromPath.substringBeforeLast('/', "").split('/').filter { it.isNotEmpty() }.toMutableList()
        }
        for (segment in clean.split('/')) {
            when (segment) {
                "", "." -> Unit
                ".." -> if (segments.isNotEmpty()) segments.removeAt(segments.size - 1)
                else -> segments += segment
            }
        }
        return segments.joinToString("/")
    }

    // MARK: - Sources

    private fun readCatalog(assets: File): List<com.simonkaring.voltlink.core.vehicles.VehicleBrand> {
        val text = File(assets, "vehicle_catalog.json").takeIf { it.isFile }?.readText().orEmpty()
        return VehicleCatalog.parse(text)
    }

    private fun readCuratedDtcs(assets: File): List<CuratedDtc> {
        val text = File(assets, "dtc_definitions.json").takeIf { it.isFile }?.readText()
            ?: error("Curated DTC seed is missing: ${File(assets, "dtc_definitions.json").path}")
        return json.decodeFromString<List<CuratedDtc>>(text)
    }

    @Serializable
    private data class CuratedDtc(
        val code: String,
        val title: String,
        val category: String,
        val severity: String,
        val description: String = "",
        val symptoms: List<String> = emptyList(),
        val possibleFixes: List<String> = emptyList(),
    )
}
